public class BuddyLocationTest
{
	@Test
	public void validatesWorldCoordinateBounds()
	{
		assertTrue(new BuddyLocation(0, 0, -1).isValid());
		assertTrue(new BuddyLocation(16_383, 16_383, 3).isValid());
