package com.buddies.presence;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

import com.buddies.location.BuddyLocation;
import com.buddies.model.BuddyPresence;
import com.google.gson.Gson;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;
import org.junit.Test;

public class PresenceClientIntegrationTest
{
	@Test
	public void javaClientExchangesPresenceWithLiveServer() throws Exception
	{
		String url = System.getenv("BUDDIES_INTEGRATION_URL");
		assumeTrue("Set BUDDIES_INTEGRATION_URL to run the live presence test", url != null && !url.isEmpty());

		CountDownLatch connected = new CountDownLatch(2);
		CountDownLatch received = new CountDownLatch(1);
		AtomicReference<BuddyPresence> peerPresence = new AtomicReference<>();
		OkHttpClient httpClient = new OkHttpClient();
		ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
		PresenceClient sender = new PresenceClient(httpClient, new Gson(), scheduler,
			status -> countConnected(status, connected), presence -> { });
		PresenceClient peer = new PresenceClient(httpClient, new Gson(), scheduler,
			status -> countConnected(status, connected), presence ->
			{
				peerPresence.set(presence);
				received.countDown();
			});

		try
		{
			sender.connect(url);
			peer.connect(url);
			assertTrue("Clients did not connect", connected.await(10, TimeUnit.SECONDS));

			BuddyPresence payload = new BuddyPresence(
				"Java Client",
				302,
				new BuddyLocation(3200, 3201, 0),
				"Fishing",
				System.currentTimeMillis());
			for (int attempt = 0; attempt < 5 && received.getCount() > 0; attempt++)
			{
				sender.broadcast(payload);
				received.await(250, TimeUnit.MILLISECONDS);
			}

			assertEquals("Peer did not receive Java client presence", 0, received.getCount());
			BuddyPresence actual = peerPresence.get();
			assertNotNull(actual);
			assertEquals("Java Client", actual.getName());
			assertEquals(302, actual.getWorld());
			assertEquals(new BuddyLocation(3200, 3201, 0), actual.getLocation());
			assertEquals("Fishing", actual.getActivity());
			assertTrue(actual.getUpdatedAt() > 0);
		}
		finally
		{
			sender.close();
			peer.close();
			scheduler.shutdownNow();
			httpClient.dispatcher().executorService().shutdown();
			httpClient.connectionPool().evictAll();
		}
	}

	private static void countConnected(PresenceStatus status, CountDownLatch latch)
	{
		if (status == PresenceStatus.CONNECTED)
		{
			latch.countDown();
		}
	}
}

package com.buddies.presence;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.buddies.model.BuddyPresence;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;
import okio.ByteString;
import org.junit.After;
import org.junit.Test;

public class PresenceClientTest
{
	private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();

	@After
	public void shutDown()
	{
		scheduler.shutdownNow();
	}

	@Test
	public void privacyFieldsAreSerializedAsExplicitNulls()
	{
		PresenceClient client = newClient(new FakeWebSocketFactory(), status -> { }, presence -> { });
		String json = client.encode(new BuddyPresence("Alice", 302, null, null, 123));
		assertTrue(json.contains("\"location\":null"));
		assertTrue(json.contains("\"activity\":null"));
	}

	@Test
	public void parsesOnlyHttpServerAddresses()
	{
		assertTrue(PresenceClient.parseServerAddress("localhost:3000").toString().startsWith("http://"));
		assertTrue(PresenceClient.parseServerAddress("https://example.com/").toString().startsWith("https://"));
		assertNull(PresenceClient.parseServerAddress("ftp://example.com"));
		assertNull(PresenceClient.parseServerAddress(" "));
		assertEquals("ws://localhost:3000/presence/v1", PresenceClient.toWebSocketEndpoint(
			PresenceClient.parseServerAddress("localhost:3000")).toString());
		assertEquals("wss://example.com/base/presence/v1", PresenceClient.toWebSocketEndpoint(
			PresenceClient.parseServerAddress("https://example.com/base/")).toString());
	}

	@Test
	public void malformedSnapshotEntryDoesNotBlockValidEntries()
	{
		List<BuddyPresence> received = new ArrayList<>();
		PresenceClient client = newClient(new FakeWebSocketFactory(), status -> { }, received::add);
		client.handlePayload("{\"bad\":{\"version\":\"not-a-number\"},"
			+ "\"Alice\":{\"version\":1,\"name\":\"Alice\",\"world\":302,"
			+ "\"location\":null,\"activity\":null,\"updatedAt\":123}}");

		assertEquals(1, received.size());
		assertEquals("Alice", received.get(0).getName());
	}

	@Test
	public void snapshotCanContainAPlayerNamedName()
	{
		List<BuddyPresence> received = new ArrayList<>();
		PresenceClient client = newClient(new FakeWebSocketFactory(), status -> { }, received::add);
		client.handlePayload("{\"name\":{\"version\":1,\"name\":\"Name\",\"world\":302,"
			+ "\"location\":null,\"activity\":null,\"updatedAt\":123}}");

		assertEquals(1, received.size());
		assertEquals("Name", received.get(0).getName());
	}

	@Test
	public void exchangesVersionedWebSocketMessages()
	{
		FakeWebSocketFactory factory = new FakeWebSocketFactory();
		List<PresenceStatus> statuses = new ArrayList<>();
		List<BuddyPresence> received = new ArrayList<>();
		PresenceClient client = newClient(factory, statuses::add, received::add);

		client.connect("https://example.com");
		assertEquals(PresenceStatus.CONNECTING, client.getStatus());
		assertEquals("/presence/v1", factory.request.url().encodedPath());
		assertTrue(factory.request.url().isHttps());

		factory.open();
		JsonObject join = parse(factory.socket.messages.get(0));
		assertEquals("join", join.get("type").getAsString());
		assertEquals(
			"d1113c0686c0aed2606c7fff822dd04031793e1280630c422a51a1ece41abbee",
			join.get("room").getAsString());
		assertEquals(PresenceStatus.CONNECTING, client.getStatus());

		factory.message("{\"type\":\"joined\"}");
		assertEquals(PresenceStatus.CONNECTED, client.getStatus());

		client.broadcast(new BuddyPresence("Alice", 302, null, null, 123));
		client.requestSnapshot();
		assertEquals("broadcast", parse(factory.socket.messages.get(1)).get("type").getAsString());
		assertEquals("snapshot", parse(factory.socket.messages.get(2)).get("type").getAsString());

		factory.message("{\"type\":\"presence\",\"presence\":{"
			+ "\"version\":1,\"name\":\"Bob\",\"world\":303,"
			+ "\"location\":null,\"activity\":null,\"updatedAt\":124}}");
		factory.message("{\"type\":\"snapshot\",\"presences\":{\"Carol\":{"
			+ "\"version\":1,\"name\":\"Carol\",\"world\":304,"
			+ "\"location\":null,\"activity\":null,\"updatedAt\":125}}}");

		assertEquals(2, received.size());
		assertEquals("Bob", received.get(0).getName());
		assertEquals("Carol", received.get(1).getName());
		assertTrue(statuses.contains(PresenceStatus.CONNECTED));

		client.close();
		assertTrue(factory.socket.cancelled);
		assertEquals(PresenceStatus.DISABLED, client.getStatus());
	}

	private PresenceClient newClient(
		WebSocket.Factory factory,
		java.util.function.Consumer<PresenceStatus> statusListener,
		java.util.function.Consumer<BuddyPresence> presenceListener)
	{
		return new PresenceClient(factory, new Gson(), scheduler, statusListener, presenceListener);
	}

	private static JsonObject parse(String json)
	{
		return new JsonParser().parse(json).getAsJsonObject();
	}

	private static final class FakeWebSocketFactory implements WebSocket.Factory
	{
		private Request request;
		private WebSocketListener listener;
		private FakeWebSocket socket;

		@Override
		public WebSocket newWebSocket(Request request, WebSocketListener listener)
		{
			this.request = request;
			this.listener = listener;
			this.socket = new FakeWebSocket(request);
			return socket;
		}

		private void open()
		{
			listener.onOpen(socket, null);
		}

		private void message(String message)
		{
			listener.onMessage(socket, message);
		}
	}

	private static final class FakeWebSocket implements WebSocket
	{
		private final Request request;
		private final List<String> messages = new ArrayList<>();
		private boolean cancelled;

		private FakeWebSocket(Request request)
		{
			this.request = request;
		}

		@Override
		public Request request()
		{
			return request;
		}

		@Override
		public long queueSize()
		{
			return 0;
		}

		@Override
		public boolean send(String text)
		{
			messages.add(text);
			return true;
		}

		@Override
		public boolean send(ByteString bytes)
		{
			return false;
		}

		@Override
		public boolean close(int code, String reason)
		{
			return true;
		}

		@Override
		public void cancel()
		{
			cancelled = true;
		}
	}
}

package com.buddies.model;

import com.buddies.location.BuddyLocation;

public final class BuddyPresence
{
	public static final int CURRENT_VERSION = 1;

	private int version;
	private String name;
	private int world;
	private BuddyLocation location;
	private String activity;
	private long updatedAt;

	@SuppressWarnings("unused")
	private BuddyPresence()
	{
		// Gson constructor.
	}

	public BuddyPresence(String name, int world, BuddyLocation location, String activity, long updatedAt)
	{
		this.version = CURRENT_VERSION;
		this.name = name;
		this.world = world;
		this.location = location;
		this.activity = activity;
		this.updatedAt = updatedAt;
	}

	public int getVersion()
	{
		return version;
	}

	public String getName()
	{
		return name;
	}

	public int getWorld()
	{
		return world;
	}

	public BuddyLocation getLocation()
	{
		return location;
	}

	public String getActivity()
	{
		return activity;
	}

	public long getUpdatedAt()
	{
		return updatedAt;
	}
}

package com.buddies.model;

import com.buddies.location.BuddyLocation;

public final class Buddy
{
	private final String name;
	private int world;
	private BuddyLocation location;
	private String activity;
	private long presenceReceivedAt;
	private long presenceSourceAt;
	private long lastSeenAt;

	Buddy(String name, int world)
	{
		this.name = name;
		this.world = Math.max(0, world);
	}

	private Buddy(Buddy source)
	{
		name = source.name;
		world = source.world;
		location = source.location;
		activity = source.activity;
		presenceReceivedAt = source.presenceReceivedAt;
		presenceSourceAt = source.presenceSourceAt;
		lastSeenAt = source.lastSeenAt;
	}

	Buddy copy()
	{
		return new Buddy(this);
	}

	void setWorld(int newWorld, long now)
	{
		newWorld = Math.max(0, newWorld);
		if (world > 0 && newWorld == 0)
		{
			lastSeenAt = now;
			clearPresence();
		}
		world = newWorld;
	}

	void applyPresence(BuddyPresence presence, long receivedAt)
	{
		location = presence.getLocation();
		activity = presence.getActivity();
		presenceSourceAt = presence.getUpdatedAt();
		presenceReceivedAt = receivedAt;
	}

	void clearPresence()
	{
		location = null;
		activity = null;
		presenceSourceAt = 0;
		presenceReceivedAt = 0;
	}

	public String getName()
	{
		return name;
	}

	public int getWorld()
	{
		return world;
	}

	public boolean isOnline()
	{
		return world > 0;
	}

	public BuddyLocation getLocation()
	{
		return location;
	}

	public String getActivity()
	{
		return activity;
	}

	public long getPresenceReceivedAt()
	{
		return presenceReceivedAt;
	}

	public long getPresenceSourceAt()
	{
		return presenceSourceAt;
	}

	public long getLastSeenAt()
	{
		return lastSeenAt;
	}

	public boolean hasFreshPresence(long now, long maxAgeMillis)
	{
		return isOnline()
			&& presenceReceivedAt > 0
			&& presenceSourceAt > 0
			&& now >= presenceReceivedAt
			&& now - presenceReceivedAt <= maxAgeMillis
			&& Math.max(0, now - presenceSourceAt) <= maxAgeMillis;
	}

	public boolean hasFreshLocation(long now, long maxAgeMillis)
	{
		return location != null && hasFreshPresence(now, maxAgeMillis);
	}
}

package com.buddies.model;

import com.buddies.location.BuddyLocation;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

public final class BuddyDirectory
{
	private static final int MAX_ACTIVITY_LENGTH = 40;
	private static final long MAX_FUTURE_SKEW_MILLIS = 5 * 60_000L;

	private final Map<String, Buddy> buddies = new LinkedHashMap<>();

	public synchronized boolean syncFriends(Map<String, Integer> friendWorlds, long now)
	{
		boolean changed = false;
		Set<String> incoming = new HashSet<>();

		for (Map.Entry<String, Integer> entry : friendWorlds.entrySet())
		{
			String name = sanitizeDisplayName(entry.getKey());
			if (name.isEmpty())
			{
				continue;
			}

			String key = normalizeName(name);
			incoming.add(key);
			int world = entry.getValue() == null ? 0 : Math.max(0, entry.getValue());
			Buddy buddy = buddies.get(key);
			if (buddy == null)
			{
				buddies.put(key, new Buddy(name, world));
				changed = true;
			}
			else if (buddy.getWorld() != world)
			{
				buddy.setWorld(world, now);
				changed = true;
			}
		}

		if (buddies.keySet().removeIf(key -> !incoming.contains(key)))
		{
			changed = true;
		}
		return changed;
	}

	public synchronized boolean applyPresence(BuddyPresence presence, long receivedAt)
	{
		if (!isValidPresence(presence, receivedAt))
		{
			return false;
		}

		Buddy buddy = buddies.get(normalizeName(presence.getName()));
		if (buddy == null || !buddy.isOnline() || presence.getUpdatedAt() <= buddy.getPresenceSourceAt())
		{
			return false;
		}

		BuddyLocation location = presence.getLocation();
		if (location != null && !location.isValid())
		{
			return false;
		}

		buddy.applyPresence(new BuddyPresence(
			buddy.getName(),
			presence.getWorld(),
			location,
			sanitizeActivity(presence.getActivity()),
			presence.getUpdatedAt()), receivedAt);
		return true;
	}

	public synchronized void clearPresence()
	{
		for (Buddy buddy : buddies.values())
		{
			buddy.clearPresence();
		}
	}

	public synchronized List<Buddy> snapshot()
	{
		List<Buddy> snapshot = new ArrayList<>();
		for (Buddy buddy : buddies.values())
		{
			snapshot.add(buddy.copy());
		}
		snapshot.sort(Comparator
			.comparing(Buddy::isOnline).reversed()
			.thenComparing(Buddy::getName, String.CASE_INSENSITIVE_ORDER));
		return snapshot;
	}

	public synchronized Buddy find(String name)
	{
		Buddy buddy = buddies.get(normalizeName(name));
		return buddy == null ? null : buddy.copy();
	}

	public synchronized boolean isFriend(String name)
	{
		return buddies.containsKey(normalizeName(name));
	}

	public synchronized int size()
	{
		return buddies.size();
	}

	private static boolean isValidPresence(BuddyPresence presence, long receivedAt)
	{
		return presence != null
			&& presence.getVersion() == BuddyPresence.CURRENT_VERSION
			&& presence.getName() != null
			&& !sanitizeDisplayName(presence.getName()).isEmpty()
			&& presence.getUpdatedAt() > 0
			&& presence.getUpdatedAt() <= receivedAt + MAX_FUTURE_SKEW_MILLIS;
	}

	static String normalizeName(String name)
	{
		return sanitizeDisplayName(name).toLowerCase(Locale.ROOT);
	}

	private static String sanitizeDisplayName(String name)
	{
		if (name == null)
		{
			return "";
		}
		return name.replace('\u00a0', ' ')
			.replace('_', ' ')
			.trim()
			.replaceAll("\\s+", " ");
	}

	private static String sanitizeActivity(String activity)
	{
		if (activity == null)
		{
			return null;
		}
		String clean = activity.trim();
		if (clean.isEmpty())
		{
			return null;
		}
		return clean.length() <= MAX_ACTIVITY_LENGTH
			? clean
			: clean.substring(0, MAX_ACTIVITY_LENGTH);
	}
}

package com.buddies.location;

import java.util.Objects;
import net.runelite.api.coords.WorldPoint;

public final class BuddyLocation
{
	private final int x;
	private final int y;
	private final int plane;

	public BuddyLocation(WorldPoint point)
	{
		this(point.getX(), point.getY(), point.getPlane());
	}

	public BuddyLocation(int x, int y, int plane)
	{
		this.x = x;
		this.y = y;
		this.plane = plane;
	}

	public int getX()
	{
		return x;
	}

	public int getY()
	{
		return y;
	}

	public int getPlane()
	{
		return plane;
	}

	public boolean isValid()
	{
		return x >= 0 && x <= 16_383
			&& y >= 0 && y <= 16_383
			&& plane >= -1 && plane <= 3;
	}

	public WorldPoint toWorldPoint()
	{
		return new WorldPoint(x, y, plane);
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof BuddyLocation))
		{
			return false;
		}
		BuddyLocation that = (BuddyLocation) other;
		return x == that.x && y == that.y && plane == that.plane;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(x, y, plane);
	}
}

