	{
	}

	public static String resolve(BuddyLocation location)
	{
		if (location == null)
		{
			return "unknown";
		}

		WorldPoint point = location.toWorldPoint();
		NamedArea area = findArea(point, SPECIAL_AREAS);
		if (area != null)
		{
			return area.name;
		}

		area = findArea(point, SPECIFIC_AREAS);
		if (area != null)
		{
			return area.name;
		}

		NamedRegion bossRegion = findRegion(point, BOSS_REGIONS);
		if (bossRegion != null)
		{
			return bossRegion.name;
		}

		NamedRegion raidRegion = findRegion(point, RAID_REGIONS);
		if (raidRegion != null)
		{
			return raidRegion.name;
		}

		area = findArea(point, RAID_AREAS);
		if (area != null)
		{
			return area.name;
		}

		area = findArea(point, REGIONS);
		if (area != null)
		{
			return area.name;
		}

		area = findArea(point, FALLBACK_AREAS);
		if (area != null)
		{
			return area.name;
		}

		return "unknown area";
	}

	private static NamedArea findArea(WorldPoint point, List<NamedArea> areas)
	{
		for (NamedArea area : areas)
		{
			if (area.contains(point))
			{
				return area;
			}
		}
		return null;
	}

	private static NamedRegion findRegion(WorldPoint point, List<NamedRegion> regions)
	{
		int regionId = ((point.getX() >> 6) << 8) | (point.getY() >> 6);
		for (NamedRegion region : regions)
		{
			if (region.contains(regionId))
			{
				return region;
			}
		}
		return null;
	}

	private static NamedArea area(String name, int minX, int minY, int maxX, int maxY)
	{
		return new NamedArea(name, minX, minY, maxX, maxY);
	}

	private static NamedRegion region(String name, int... regionIds)
	{
		return new NamedRegion(name, regionIds);
	}

	private static final class NamedArea
	{
		private final String name;
		private final int minX;
		private final int minY;
		private final int maxX;
		private final int maxY;

		private NamedArea(String name, int minX, int minY, int maxX, int maxY)
		{
			this.name = name;
			this.minX = minX;
			this.minY = minY;
			this.maxX = maxX;
			this.maxY = maxY;
		}

		private boolean contains(WorldPoint point)
		{
			return point.getX() >= minX
				&& point.getX() <= maxX
				&& point.getY() >= minY
				&& point.getY() <= maxY;
		}
	}

	private static final class NamedRegion
	{
		private final String name;
		private final int[] regionIds;

		private NamedRegion(String name, int[] regionIds)
		{
			this.name = name;
			this.regionIds = regionIds;
		}

		private boolean contains(int regionId)
		{
			for (int candidate : regionIds)
			{
				if (candidate == regionId)
				{
					return true;
				}
			}
			return false;
		}
	}
}

package com.buddies.ui;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.table.AbstractTableModel;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.hiscore.Skill;
import net.runelite.client.util.QuantityFormatter;

final class HiscoreTableModel extends AbstractTableModel
{
	enum View
	{
		STATS,
		HIGHSCORES
	}

	private final View view;
	private final List<HiscoreSkill> rows;
	private HiscoreResult result;

	HiscoreTableModel(View view)
	{
		this.view = view;
		List<HiscoreSkill> values = new ArrayList<>();
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			HiscoreSkillType type = skill.getType();
			if (view == View.STATS
				? type == HiscoreSkillType.OVERALL || type == HiscoreSkillType.SKILL
				: type == HiscoreSkillType.ACTIVITY || type == HiscoreSkillType.BOSS)
			{
				values.add(skill);
			}
		}
		rows = Collections.unmodifiableList(values);
	}

	void setResult(HiscoreResult result)
	{
		this.result = result;
		fireTableDataChanged();
	}

	HiscoreSkill getSkill(int row)
	{
		return rows.get(row);
	}

	@Override
	public int getRowCount()
	{
		return rows.size();
	}

	@Override
	public int getColumnCount()
	{
		return 3;
	}

	@Override
	public String getColumnName(int column)
	{
		if (column == 0)
		{
			return view == View.STATS ? "Skill" : "Record";
		}
		if (column == 1)
		{
			return view == View.STATS ? "Level" : "Score";
		}
		return "Rank";
	}

	@Override
	public Object getValueAt(int rowIndex, int columnIndex)
	{
		HiscoreSkill hiscoreSkill = rows.get(rowIndex);
		if (columnIndex == 0)
		{
			return hiscoreSkill.getName();
		}
		if (result == null)
		{
			return "--";
		}

		Skill skill = result.getSkill(hiscoreSkill);
		if (skill == null)
		{
			return "-";
		}
		if (columnIndex == 1)
		{
			int level = skill.getLevel();
			return level < 0 ? "-" : QuantityFormatter.formatNumber(level);
		}
		int rank = skill.getRank();
		return rank < 0 ? "-" : QuantityFormatter.formatNumber(rank);
	}
}

