import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public class BuddiesPanel extends PluginPanel
{
	private static final String FRIENDS = "friends";
	private static final String EMPTY = "empty";
	private static final Color ONLINE = new Color(46, 204, 113);

	private final BuddiesPlugin plugin;
	private final DefaultListModel<Buddy> friendModel = new DefaultListModel<>();
	private final JList<Buddy> friendList = new JList<>(friendModel);
	private final JPanel friendCards = new JPanel(new CardLayout());
	private final JPanel detailsPanel = new JPanel();
	private final JLabel connectionLabel = new JLabel("Sync off");
	private final JLabel usernameLabel = new JLabel();
	private final JLabel worldLabel = new JLabel();
	private final JLabel activityLabel = new JLabel();
	private final JLabel locationLabel = new JLabel();
	private final JLabel hiscoreStateLabel = new JLabel(" ");
	private final JLabel statsSummaryLabel = new JLabel("Combat --    Total --");
	private final HiscoreTableModel statsModel = new HiscoreTableModel(HiscoreTableModel.View.STATS);
	private final HiscoreTableModel highscoresModel = new HiscoreTableModel(HiscoreTableModel.View.HIGHSCORES);
	private final Map<String, HiscoreResult> hiscoreCache = new HashMap<>();
	private final Set<String> loadingHiscores = new HashSet<>();

	private volatile String selectedBuddyName;
	private long freshnessMillis;
	private boolean applyingFriends;

	@Inject
	public BuddiesPanel(BuddiesPlugin plugin, SpriteManager spriteManager)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(buildHeader());
		content.add(Box.createVerticalStrut(8));
		content.add(buildFriendList());
		content.add(Box.createVerticalStrut(8));
		content.add(buildDetails(spriteManager));
		add(content, BorderLayout.CENTER);
	}

	public void updateFriends(List<Buddy> buddies, long freshness)
	{
		List<Buddy> snapshot = new ArrayList<>(buddies);
		SwingUtilities.invokeLater(() -> applyFriends(snapshot, freshness));
	}

	public void refreshBuddy(Buddy buddy, long freshness)
	{
		SwingUtilities.invokeLater(() ->
		{
			freshnessMillis = freshness;
			if (buddy != null && buddy.getName().equalsIgnoreCase(selectedBuddyName))
			{
				applyBuddySummary(buddy);
			}
		});
	}

	public void setPresenceStatus(PresenceStatus status)
	{
		SwingUtilities.invokeLater(() ->
		{
			switch (status)
			{
				case CONNECTED:
					connectionLabel.setText("Live");
					connectionLabel.setForeground(ONLINE);
					break;
				case CONNECTING:
					connectionLabel.setText("Connecting");
					connectionLabel.setForeground(ColorScheme.BRAND_ORANGE);
					break;
				case DISCONNECTED:
					connectionLabel.setText("Offline");
					connectionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
					break;
				default:
					connectionLabel.setText("Sync off");
					connectionLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			}
		});
	}

	public void setHiscoresLoading(String name)
	{
		SwingUtilities.invokeLater(() ->
		{
			loadingHiscores.add(key(name));
			if (name.equalsIgnoreCase(selectedBuddyName) && !hiscoreCache.containsKey(key(name)))
			{
				statsModel.setResult(null);
				highscoresModel.setResult(null);
				statsSummaryLabel.setText("Combat --    Total --");
				hiscoreStateLabel.setText("Loading hiscores...");
			}
		});
	}

	public void setHiscores(String name, HiscoreResult result, String error)
	{
		SwingUtilities.invokeLater(() ->
		{
			String key = key(name);
			loadingHiscores.remove(key);
			if (result != null)
			{
				hiscoreCache.put(key, result);
			}
			if (name.equalsIgnoreCase(selectedBuddyName))
			{
				applyHiscores(result, error);
			}
		});
	}

	public String getSelectedBuddyName()
	{
		return selectedBuddyName;
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setAlignmentX(LEFT_ALIGNMENT);
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JLabel title = new JLabel("Buddies");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);

		connectionLabel.setFont(FontManager.getRunescapeSmallFont());
		connectionLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		connectionLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);

		JButton refresh = new JButton("Refresh");
		refresh.setToolTipText("Refresh friends and selected hiscores");
		refresh.setFocusable(false);
		refresh.addActionListener(event -> plugin.refreshSelectedBuddy());

		JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 5, 0));
		right.setBackground(ColorScheme.DARK_GRAY_COLOR);
		right.add(connectionLabel);
		right.add(refresh);
		header.add(title, BorderLayout.WEST);
		header.add(right, BorderLayout.EAST);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, header.getPreferredSize().height));
		return header;
	}

	private JPanel buildFriendList()
	{
		friendList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		friendList.setCellRenderer(new FriendListCellRenderer());
		friendList.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		friendList.setFixedCellHeight(34);
		friendList.addListSelectionListener(event ->
		{
			if (!event.getValueIsAdjusting() && !applyingFriends)
			{
				selectBuddy(friendList.getSelectedValue(), true);
			}
		});

		JScrollPane scroll = new JScrollPane(friendList);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		scroll.setPreferredSize(new Dimension(220, 142));
		scroll.getVerticalScrollBar().setUnitIncrement(12);

		JLabel empty = new JLabel("No friends available", SwingConstants.CENTER);
		empty.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		empty.setFont(FontManager.getRunescapeFont());
		JPanel emptyPanel = new JPanel(new BorderLayout());
		emptyPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		emptyPanel.add(empty, BorderLayout.CENTER);
		emptyPanel.setPreferredSize(new Dimension(220, 72));

		friendCards.setBackground(ColorScheme.DARK_GRAY_COLOR);
		friendCards.setAlignmentX(LEFT_ALIGNMENT);
		friendCards.add(scroll, FRIENDS);
		friendCards.add(emptyPanel, EMPTY);
		friendCards.setMaximumSize(new Dimension(Integer.MAX_VALUE, scroll.getPreferredSize().height));
		return friendCards;
	}

	private JPanel buildDetails(SpriteManager spriteManager)
	{
		detailsPanel.setLayout(new BoxLayout(detailsPanel, BoxLayout.Y_AXIS));
		detailsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		detailsPanel.setAlignmentX(LEFT_ALIGNMENT);
		detailsPanel.add(buildSummary());
		detailsPanel.add(Box.createVerticalStrut(6));

		hiscoreStateLabel.setFont(FontManager.getRunescapeSmallFont());
		hiscoreStateLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		hiscoreStateLabel.setAlignmentX(LEFT_ALIGNMENT);
		detailsPanel.add(hiscoreStateLabel);
		detailsPanel.add(Box.createVerticalStrut(3));
		detailsPanel.add(buildHiscoreTabs(spriteManager));
		detailsPanel.setVisible(false);
		return detailsPanel;
	}

	private JPanel buildSummary()
	{
		JPanel summary = new JPanel();
		summary.setLayout(new BoxLayout(summary, BoxLayout.Y_AXIS));
		summary.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		summary.setBorder(new EmptyBorder(8, 9, 8, 9));
		summary.setAlignmentX(LEFT_ALIGNMENT);

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		titleRow.setAlignmentX(LEFT_ALIGNMENT);
		usernameLabel.setFont(FontManager.getRunescapeBoldFont());
		usernameLabel.setForeground(Color.WHITE);
		worldLabel.setFont(FontManager.getRunescapeFont());
		worldLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		titleRow.add(usernameLabel, BorderLayout.CENTER);
		titleRow.add(worldLabel, BorderLayout.EAST);

		activityLabel.setFont(FontManager.getRunescapeSmallFont());
		locationLabel.setFont(FontManager.getRunescapeSmallFont());
		activityLabel.setAlignmentX(LEFT_ALIGNMENT);
		locationLabel.setAlignmentX(LEFT_ALIGNMENT);
		activityLabel.setBorder(new EmptyBorder(5, 0, 0, 0));
		locationLabel.setBorder(new EmptyBorder(3, 0, 0, 0));
		summary.add(titleRow);
		summary.add(activityLabel);
		summary.add(locationLabel);
		summary.setMaximumSize(new Dimension(Integer.MAX_VALUE, summary.getPreferredSize().height));
		return summary;
	}

	private JTabbedPane buildHiscoreTabs(SpriteManager spriteManager)
	{
		JTable statsTable = buildTable(statsModel, spriteManager);
		JTable highscoresTable = buildTable(highscoresModel, spriteManager);

		JPanel stats = new JPanel(new BorderLayout());
		stats.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		statsSummaryLabel.setBorder(new EmptyBorder(6, 7, 6, 7));
		statsSummaryLabel.setFont(FontManager.getRunescapeBoldFont());
		statsSummaryLabel.setForeground(ColorScheme.BRAND_ORANGE);
		stats.add(statsSummaryLabel, BorderLayout.NORTH);
		stats.add(tableScroll(statsTable), BorderLayout.CENTER);

		JTabbedPane tabs = new JTabbedPane();
		tabs.addTab("Stats", stats);
		tabs.addTab("Highscores", tableScroll(highscoresTable));
		tabs.setPreferredSize(new Dimension(220, 430));
		tabs.setMinimumSize(new Dimension(180, 300));
		tabs.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		tabs.setAlignmentX(LEFT_ALIGNMENT);
		return tabs;
	}

	private JTable buildTable(HiscoreTableModel model, SpriteManager spriteManager)
	{
		JTable table = new JTable(model);
		table.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		table.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		table.setSelectionBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
		table.setSelectionForeground(Color.WHITE);
		table.setGridColor(ColorScheme.DARK_GRAY_COLOR);
		table.setShowVerticalLines(false);
		table.setRowHeight(24);
		table.setAutoCreateRowSorter(true);
		table.getTableHeader().setReorderingAllowed(false);
		TableColumn nameColumn = table.getColumnModel().getColumn(0);
		TableColumn valueColumn = table.getColumnModel().getColumn(1);
		TableColumn rankColumn = table.getColumnModel().getColumn(2);
		nameColumn.setPreferredWidth(108);
		nameColumn.setMinWidth(80);
		valueColumn.setPreferredWidth(48);
		valueColumn.setMinWidth(42);
		rankColumn.setPreferredWidth(56);
		rankColumn.setMinWidth(48);
		nameColumn.setCellRenderer(new HiscoreNameRenderer(model, spriteManager));

		DefaultTableCellRenderer numberRenderer = new DefaultTableCellRenderer();
		numberRenderer.setHorizontalAlignment(SwingConstants.RIGHT);
		numberRenderer.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		valueColumn.setCellRenderer(numberRenderer);
		rankColumn.setCellRenderer(numberRenderer);
		return table;
	}

	private JScrollPane tableScroll(JTable table)
	{
		JScrollPane scroll = new JScrollPane(table);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(14);
		return scroll;
	}

	private void applyFriends(List<Buddy> buddies, long freshness)
	{
		freshnessMillis = freshness;
		String previous = selectedBuddyName;
		applyingFriends = true;
		friendModel.clear();
		for (Buddy buddy : buddies)
		{
			friendModel.addElement(buddy);
		}

		if (buddies.isEmpty())
		{
			selectedBuddyName = null;
			friendList.clearSelection();
			detailsPanel.setVisible(false);
			((CardLayout) friendCards.getLayout()).show(friendCards, EMPTY);
			applyingFriends = false;
			return;
		}

		((CardLayout) friendCards.getLayout()).show(friendCards, FRIENDS);
		int selectedIndex = 0;
		if (previous != null)
		{
			for (int index = 0; index < buddies.size(); index++)
			{
				if (buddies.get(index).getName().equalsIgnoreCase(previous))
				{
					selectedIndex = index;
					break;
				}
			}
		}
		friendList.setSelectedIndex(selectedIndex);
		friendList.ensureIndexIsVisible(selectedIndex);
		applyingFriends = false;
		selectBuddy(buddies.get(selectedIndex), !buddies.get(selectedIndex).getName().equalsIgnoreCase(previous));
	}

	private void selectBuddy(Buddy buddy, boolean requestHiscores)
	{
		if (buddy == null)
		{
			return;
		}
		selectedBuddyName = buddy.getName();
		detailsPanel.setVisible(true);
		applyBuddySummary(buddy);

		HiscoreResult cached = hiscoreCache.get(key(buddy.getName()));
		if (cached != null)
		{
			applyHiscores(cached, null);
		}
		else
		{
			statsModel.setResult(null);
			highscoresModel.setResult(null);
			statsSummaryLabel.setText("Combat --    Total --");
			hiscoreStateLabel.setText("Loading hiscores...");
			if (requestHiscores || !loadingHiscores.contains(key(buddy.getName())))
			{
				plugin.requestHiscores(buddy.getName());
			}
		}
	}

	private void applyBuddySummary(Buddy buddy)
	{
		usernameLabel.setText(buddy.getName());
		worldLabel.setText(buddy.isOnline() ? "W" + buddy.getWorld() : "Offline");
		worldLabel.setForeground(buddy.isOnline() ? ONLINE : ColorScheme.MEDIUM_GRAY_COLOR);

		long now = System.currentTimeMillis();
		String activity = buddy.isOnline()
			? buddy.hasFreshPresence(now, freshnessMillis) && buddy.getActivity() != null
				? displayActivity(buddy.getActivity())
				: "In game"
			: "Inactive";
		activityLabel.setText(pair("Activity", activity));

		BuddyLocation location = buddy.getLocation();
		String locationText;
		if (!buddy.isOnline())
		{
			locationText = "Offline";
		}
		else if (buddy.hasFreshLocation(now, freshnessMillis))
		{
			locationText = LocationResolver.resolve(location);
		}
		else
		{
			locationText = "Not shared";
		}
		locationLabel.setText(pair("Location", locationText));
		locationLabel.setToolTipText(buddy.hasFreshLocation(now, freshnessMillis)
			? "Tile " + location.getX() + ", " + location.getY() + ", " + location.getPlane()
			: null);
	}

	static String displayActivity(String activity)
	{
		return activity.startsWith("Training ")
			|| activity.startsWith("Fighting ")
			|| "In combat".equals(activity)
			? activity
			: "Training " + activity;
	}

	private void applyHiscores(HiscoreResult result, String error)
	{
		statsModel.setResult(result);
		highscoresModel.setResult(result);
		if (result == null)
		{
			statsSummaryLabel.setText("Combat --    Total --");
			hiscoreStateLabel.setText(error == null ? "No hiscore data" : error);
			return;
		}
		hiscoreStateLabel.setText(" ");
		statsSummaryLabel.setText("Combat " + combatLevel(result) + "    Total " + totalLevel(result));
	}

	private static String combatLevel(HiscoreResult result)
	{
		Skill attack = result.getSkill(HiscoreSkill.ATTACK);
		Skill strength = result.getSkill(HiscoreSkill.STRENGTH);
		Skill defence = result.getSkill(HiscoreSkill.DEFENCE);
		Skill hitpoints = result.getSkill(HiscoreSkill.HITPOINTS);
		Skill magic = result.getSkill(HiscoreSkill.MAGIC);
		Skill ranged = result.getSkill(HiscoreSkill.RANGED);
		Skill prayer = result.getSkill(HiscoreSkill.PRAYER);
		if (attack == null || strength == null || defence == null || hitpoints == null
			|| magic == null || ranged == null || prayer == null)
		{
			return "--";
		}
		return Integer.toString(Experience.getCombatLevel(
			attack.getLevel(), strength.getLevel(), defence.getLevel(), hitpoints.getLevel(),
			magic.getLevel(), ranged.getLevel(), prayer.getLevel()));
	}

	private static String totalLevel(HiscoreResult result)
	{
		Skill overall = result.getSkill(HiscoreSkill.OVERALL);
		return overall == null || overall.getLevel() < 0 ? "--" : Integer.toString(overall.getLevel());
	}

	private static String pair(String key, String value)
	{
		return "<html><span style='color:#a5a5a5'>" + escape(key) + ": </span>"
			+ "<span style='color:white'>" + escape(value) + "</span></html>";
	}

	private static String escape(String value)
	{
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static String key(String name)
	{
		return name == null ? "" : name.toLowerCase(java.util.Locale.ROOT);
	}
}

package com.buddies.ui;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JTable;
import javax.swing.SwingUtilities;
import javax.swing.table.DefaultTableCellRenderer;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.ImageUtil;

final class HiscoreNameRenderer extends DefaultTableCellRenderer
{
	private final HiscoreTableModel model;
	private final SpriteManager spriteManager;
	private final Map<Integer, ImageIcon> icons = new HashMap<>();
	private final Set<Integer> pending = new HashSet<>();

	HiscoreNameRenderer(HiscoreTableModel model, SpriteManager spriteManager)
	{
		this.model = model;
		this.spriteManager = spriteManager;
		setOpaque(true);
	}

	@Override
	public Component getTableCellRendererComponent(
		JTable table,
		Object value,
		boolean selected,
		boolean focused,
		int row,
		int column)
	{
		JLabel label = (JLabel) super.getTableCellRendererComponent(
			table, value, selected, focused, row, column);
		HiscoreSkill skill = model.getSkill(table.convertRowIndexToModel(row));
		label.setToolTipText(skill.getName());
		label.setIconTextGap(5);
		label.setBackground(selected ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);

		int spriteId = skill.getSpriteId();
		label.setIcon(icons.get(spriteId));
		if (spriteId >= 0 && !icons.containsKey(spriteId) && pending.add(spriteId))
		{
			spriteManager.getSpriteAsync(spriteId, 0, sprite -> cacheSprite(table, spriteId, sprite));
		}
		return label;
	}

	private void cacheSprite(JTable table, int spriteId, BufferedImage sprite)
	{
		SwingUtilities.invokeLater(() ->
		{
			pending.remove(spriteId);
			if (sprite != null)
			{
				BufferedImage icon = ImageUtil.resizeImage(ImageUtil.resizeCanvas(sprite, 25, 25), 18, 18);
				icons.put(spriteId, new ImageIcon(icon));
				table.repaint();
			}
		});
	}
}

package com.buddies.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

public final class BuddiesIcon
{
	private BuddiesIcon()
	{
	}

	public static BufferedImage create()
	{
		return create(18);
	}

	public static BufferedImage create(int size)
	{
		if (size <= 0)
		{
			throw new IllegalArgumentException("Icon size must be positive");
		}
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.scale(size / 18.0, size / 18.0);
			graphics.setStroke(new BasicStroke(1.3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

			graphics.setColor(new Color(74, 184, 204));
			graphics.fillOval(2, 2, 6, 6);
			graphics.fillArc(-1, 8, 12, 10, 0, 180);

			graphics.setColor(new Color(220, 138, 0));
			graphics.fillOval(10, 2, 6, 6);
			graphics.fillArc(7, 8, 12, 10, 0, 180);

			graphics.setColor(new Color(225, 225, 225));
			graphics.drawOval(2, 2, 6, 6);
			graphics.drawOval(10, 2, 6, 6);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}
}

package com.buddies.presence;

import com.buddies.model.BuddyPresence;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public final class PresenceClient implements AutoCloseable
{
	private static final Logger LOG = LoggerFactory.getLogger(PresenceClient.class);
	private static final String ENDPOINT_PATH = "/presence/v1";
	// This only selects the shared relay room; it is intentionally not a secret.
	private static final String SHARED_ROOM = RoomKey.derive("buddies-presence-v1");
	private static final long JOIN_TIMEOUT_MS = 15_000L;
	private static final long MIN_RECONNECT_DELAY_MS = 1_000L;
	private static final long MAX_RECONNECT_DELAY_MS = 10_000L;

	private final WebSocket.Factory webSocketFactory;
	private final Gson gson;
	private final ScheduledExecutorService scheduler;
	private final Consumer<PresenceStatus> statusListener;
	private final Consumer<BuddyPresence> presenceListener;
	private final AtomicReference<PresenceStatus> status = new AtomicReference<>(PresenceStatus.DISABLED);

	private WebSocket socket;
	private URI endpoint;
	private String room;
	private boolean enabled;
	private long generation;
	private long reconnectDelayMs = MIN_RECONNECT_DELAY_MS;
	private ScheduledFuture<?> reconnectFuture;
	private ScheduledFuture<?> joinTimeoutFuture;

	public PresenceClient(
		WebSocket.Factory webSocketFactory,
		Gson gson,
		ScheduledExecutorService scheduler,
		Consumer<PresenceStatus> statusListener,
		Consumer<BuddyPresence> presenceListener)
	{
		this.webSocketFactory = Objects.requireNonNull(webSocketFactory);
		this.gson = Objects.requireNonNull(gson).newBuilder().serializeNulls().create();
		this.scheduler = Objects.requireNonNull(scheduler);
		this.statusListener = Objects.requireNonNull(statusListener);
		this.presenceListener = Objects.requireNonNull(presenceListener);
	}

	public synchronized void connect(String serverAddress)
	{
		stopConnection();
		URI server = parseServerAddress(serverAddress);
		if (server == null)
		{
			setStatus(PresenceStatus.DISABLED);
			return;
		}

		URI nextEndpoint = toWebSocketEndpoint(server);
		if (nextEndpoint == null)
		{
			setStatus(PresenceStatus.DISABLED);
			return;
		}

		endpoint = nextEndpoint;
		room = SHARED_ROOM;
		enabled = true;
		reconnectDelayMs = MIN_RECONNECT_DELAY_MS;
		setStatus(PresenceStatus.CONNECTING);
		openSocket(generation);
	}

	public synchronized void broadcast(BuddyPresence presence)
	{
		if (socket == null || status.get() != PresenceStatus.CONNECTED)
		{
			return;
		}

		JsonObject message = new JsonObject();
		message.addProperty("type", "broadcast");
		message.add("presence", gson.toJsonTree(presence));
		socket.send(gson.toJson(message));
	}

	public synchronized void requestSnapshot()
	{
		if (socket == null || status.get() != PresenceStatus.CONNECTED)
		{
			return;
		}

		JsonObject message = new JsonObject();
		message.addProperty("type", "snapshot");
		socket.send(gson.toJson(message));
	}

	public PresenceStatus getStatus()
	{
		return status.get();
	}

	String encode(BuddyPresence presence)
	{
		return gson.toJson(presence);
	}

	@Override
	public synchronized void close()
	{
		stopConnection();
		setStatus(PresenceStatus.DISABLED);
	}

	private synchronized void openSocket(long expectedGeneration)
	{
		if (!enabled || expectedGeneration != generation)
		{
			return;
		}

		Request request = new Request.Builder().url(endpoint.toString()).build();
		try
		{
			socket = webSocketFactory.newWebSocket(request, new Listener(expectedGeneration));
		}
		catch (RuntimeException ex)
		{
			LOG.debug("Unable to start Buddies presence connection", ex);
			socket = null;
			setStatus(PresenceStatus.DISCONNECTED);
			scheduleReconnect(expectedGeneration);
		}
	}

	private synchronized void onOpen(long expectedGeneration, WebSocket source)
	{
		if (!isCurrent(expectedGeneration, source))
		{
			source.cancel();
			return;
		}

		JsonObject message = new JsonObject();
		message.addProperty("type", "join");
		message.addProperty("room", room);
		if (!source.send(gson.toJson(message)))
		{
			onDisconnected(expectedGeneration, source, null);
			source.cancel();
			return;
		}
		scheduleJoinTimeout(expectedGeneration, source);
	}

	private void onMessage(long expectedGeneration, WebSocket source, String text)
	{
		JsonObject message;
		try
		{
			JsonElement root = new JsonParser().parse(text);
			if (!root.isJsonObject())
			{
				return;
			}
			message = root.getAsJsonObject();
		}
		catch (RuntimeException ex)
		{
			LOG.debug("Ignoring malformed Buddies WebSocket message", ex);
			return;
		}

		JsonElement typeElement = message.get("type");
		if (typeElement == null || !typeElement.isJsonPrimitive())
		{
			return;
		}

		String type;
		try
		{
			type = typeElement.getAsString();
		}
		catch (RuntimeException ex)
		{
			return;
		}

		switch (type)
		{
			case "joined":
				onJoined(expectedGeneration, source);
				break;
			case "presence":
				if (isCurrentConnection(expectedGeneration, source))
				{
					handlePayload(message.get("presence"));
				}
				break;
			case "snapshot":
				if (isCurrentConnection(expectedGeneration, source))
				{
					handlePayload(message.get("presences"));
				}
				break;
			case "error":
				onServerError(expectedGeneration, source, message);
				break;
			default:
				break;
		}
	}

	private synchronized void onJoined(long expectedGeneration, WebSocket source)
	{
		if (!isCurrent(expectedGeneration, source))
		{
			return;
		}
		cancelJoinTimeout();
		reconnectDelayMs = MIN_RECONNECT_DELAY_MS;
		setStatus(PresenceStatus.CONNECTED);
	}

	private synchronized void onServerError(
		long expectedGeneration,
		WebSocket source,
		JsonObject message)
	{
		if (!isCurrent(expectedGeneration, source))
		{
			return;
		}

		String code = jsonString(message.get("code"));
		LOG.debug("Buddies presence server rejected a message: {}", code);
		if (status.get() != PresenceStatus.CONNECTED)
		{
			onDisconnected(expectedGeneration, source, null);
			source.cancel();
		}
	}

	private synchronized void onDisconnected(
		long expectedGeneration,
		WebSocket source,
		Throwable failure)
	{
		if (!isCurrent(expectedGeneration, source))
		{
			return;
		}

		if (failure != null)
		{
			LOG.debug("Buddies presence connection failed", failure);
		}
		cancelJoinTimeout();
		socket = null;
		setStatus(PresenceStatus.DISCONNECTED);
		scheduleReconnect(expectedGeneration);
	}

	private synchronized void scheduleReconnect(long expectedGeneration)
	{
		if (!enabled || expectedGeneration != generation || reconnectFuture != null)
		{
			return;
		}

		long delay = reconnectDelayMs;
		reconnectDelayMs = Math.min(MAX_RECONNECT_DELAY_MS, reconnectDelayMs * 2L);
		try
		{
			reconnectFuture = scheduler.schedule(
				() -> reconnect(expectedGeneration), delay, TimeUnit.MILLISECONDS);
		}
		catch (RejectedExecutionException ex)
		{
			LOG.debug("Unable to schedule Buddies presence reconnect", ex);
		}
	}

	private synchronized void scheduleJoinTimeout(long expectedGeneration, WebSocket source)
	{
		cancelJoinTimeout();
		try
		{
			joinTimeoutFuture = scheduler.schedule(() ->
			{
				synchronized (PresenceClient.this)
				{
					joinTimeoutFuture = null;
					if (!isCurrent(expectedGeneration, source)
						|| status.get() == PresenceStatus.CONNECTED)
					{
						return;
					}
					onDisconnected(expectedGeneration, source, null);
					source.cancel();
				}
			}, JOIN_TIMEOUT_MS, TimeUnit.MILLISECONDS);
		}
		catch (RejectedExecutionException ex)
		{
			LOG.debug("Unable to schedule Buddies presence join timeout", ex);
		}
	}

	private synchronized void reconnect(long expectedGeneration)
	{
		reconnectFuture = null;
		if (!enabled || expectedGeneration != generation)
		{
			return;
		}
		setStatus(PresenceStatus.CONNECTING);
		openSocket(expectedGeneration);
	}

	void handlePayload(Object payload)
	{
		if (payload == null)
		{
			return;
		}

		try
		{
			JsonElement root = payload instanceof JsonElement
				? (JsonElement) payload
				: new JsonParser().parse(payload.toString());
			if (root.isJsonArray())
			{
				for (JsonElement element : root.getAsJsonArray())
				{
					emitPresence(element);
				}
				return;
			}

			if (!root.isJsonObject())
			{
				return;
			}
			JsonObject object = root.getAsJsonObject();
			JsonElement name = object.get("name");
			if (name != null && name.isJsonPrimitive())
			{
				emitPresence(object);
				return;
			}
			for (Map.Entry<String, JsonElement> entry : object.entrySet())
			{
				emitPresence(entry.getValue());
			}
		}
		catch (RuntimeException ex)
		{
			LOG.debug("Ignoring malformed Buddies presence payload", ex);
		}
	}

	private void emitPresence(JsonElement element)
	{
		if (element == null || !element.isJsonObject())
		{
			return;
		}
		try
		{
			BuddyPresence presence = gson.fromJson(element, BuddyPresence.class);
			presenceListener.accept(presence);
		}
		catch (RuntimeException ex)
		{
			LOG.debug("Ignoring malformed Buddies presence entry", ex);
		}
	}

	private synchronized void stopConnection()
	{
		enabled = false;
		generation++;
		if (reconnectFuture != null)
		{
			reconnectFuture.cancel(false);
			reconnectFuture = null;
		}
		cancelJoinTimeout();
		if (socket != null)
		{
			socket.cancel();
			socket = null;
		}
		endpoint = null;
		room = null;
	}

	private void cancelJoinTimeout()
	{
		if (joinTimeoutFuture != null)
		{
			joinTimeoutFuture.cancel(false);
			joinTimeoutFuture = null;
		}
	}

	private synchronized boolean isCurrentConnection(long expectedGeneration, WebSocket source)
	{
		return isCurrent(expectedGeneration, source) && status.get() == PresenceStatus.CONNECTED;
	}

	private boolean isCurrent(long expectedGeneration, WebSocket source)
	{
		return enabled && expectedGeneration == generation && source == socket;
	}

	private void setStatus(PresenceStatus next)
	{
		PresenceStatus previous = status.getAndSet(next);
		if (previous != next)
		{
			statusListener.accept(next);
		}
	}

	private static String jsonString(JsonElement element)
	{
		try
		{
			return element != null && element.isJsonPrimitive() ? element.getAsString() : "unknown";
		}
		catch (RuntimeException ex)
		{
			return "unknown";
		}
	}

	static URI parseServerAddress(String address)
	{
		if (address == null || address.trim().isEmpty())
		{
			return null;
		}
		String value = address.trim().replaceAll("/+$", "");
		if (value.matches("(?i)^[a-z][a-z0-9+.-]*://.*") && !value.matches("(?i)^https?://.*"))
		{
			return null;
		}
		if (!value.matches("(?i)^https?://.*"))
		{
			value = "http://" + value;
		}
		try
		{
			URI uri = URI.create(value);
			String scheme = uri.getScheme();
			return uri.getHost() != null && ("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))
				? uri
				: null;
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	static URI toWebSocketEndpoint(URI server)
	{
		String scheme = "https".equalsIgnoreCase(server.getScheme()) ? "wss" : "ws";
		String path = server.getPath();
		path = path == null ? "" : path.replaceAll("/+$", "");
		if (!path.endsWith(ENDPOINT_PATH))
		{
			path += ENDPOINT_PATH;
		}
		try
		{
			return new URI(scheme, null, server.getHost(), server.getPort(), path, null, null);
		}
		catch (URISyntaxException ex)
		{
			return null;
		}
	}

	private final class Listener extends WebSocketListener
	{
		private final long expectedGeneration;

		private Listener(long expectedGeneration)
		{
			this.expectedGeneration = expectedGeneration;
		}

		@Override
		public void onOpen(WebSocket webSocket, Response response)
		{
			PresenceClient.this.onOpen(expectedGeneration, webSocket);
		}

		@Override
		public void onMessage(WebSocket webSocket, String text)
		{
			PresenceClient.this.onMessage(expectedGeneration, webSocket, text);
		}

		@Override
		public void onClosing(WebSocket webSocket, int code, String reason)
		{
			webSocket.close(code, reason);
		}

		@Override
		public void onClosed(WebSocket webSocket, int code, String reason)
		{
			PresenceClient.this.onDisconnected(expectedGeneration, webSocket, null);
		}

		@Override
		public void onFailure(WebSocket webSocket, Throwable throwable, Response response)
		{
			PresenceClient.this.onDisconnected(expectedGeneration, webSocket, throwable);
		}
	}
}

package com.buddies.presence;

public enum PresenceStatus
{
	DISABLED,
	CONNECTING,
	CONNECTED,
	DISCONNECTED
}

package com.buddies.presence;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public final class RoomKey
{
	private RoomKey()
	{
	}

	public static String derive(String sharedKey)
	{
		String clean = sharedKey == null ? "" : sharedKey.trim();
		if (clean.isEmpty())
		{
			return "";
		}

		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256")
				.digest(clean.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(digest.length * 2);
			for (byte value : digest)
			{
				hex.append(String.format("%02x", value & 0xff));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException ex)
		{
			throw new IllegalStateException("SHA-256 is unavailable", ex);
		}
	}
}

package com.buddies;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

final class ActivityTracker
{
	static final long TRAINING_TIMEOUT_MILLIS = 30_000L;
	static final long COMBAT_GRACE_MILLIS = 5_000L;
	private static final int MAX_ACTIVITY_LENGTH = 40;

	private final Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
	private String trainingActivity;
	private long trainingObservedAt = -1L;
	private String combatActivity;
	private boolean combatActive;
	private long combatEndedAt = -1L;

	void seedExperience(Skill skill, int xp)
	{
		if (skill != null)
		{
			experience.put(skill, xp);
		}
	}

	void observeExperience(Skill skill, int xp, long now)
	{
		if (skill == null)
		{
			return;
		}

		Integer previous = experience.put(skill, xp);
		if (previous == null || xp <= previous || skill == Skill.HITPOINTS || skill == Skill.OVERALL)
		{
			return;
		}

		if (!hasCombatActivity(now))
		{
			trainingActivity = limit("Training " + skill.getName());
			trainingObservedAt = now;
		}
	}

	void observeCombat(String targetName, long now)
	{
		String cleanName = targetName == null ? "" : targetName.trim();
		combatActivity = cleanName.isEmpty()
			? "In combat"
			: limit("Fighting " + cleanName);
		combatActive = true;
		combatEndedAt = -1L;
		trainingActivity = null;
		trainingObservedAt = -1L;
	}

	void observeNoCombat(long now)
	{
		if (combatActive)
		{
			combatActive = false;
			combatEndedAt = now;
		}
	}

	String getActivity(long now)
	{
		if (hasCombatActivity(now))
		{
			return combatActivity;
		}
		return isFresh(trainingObservedAt, now, TRAINING_TIMEOUT_MILLIS) ? trainingActivity : null;
	}

	void reset()
	{
		experience.clear();
		trainingActivity = null;
		trainingObservedAt = -1L;
		combatActivity = null;
		combatActive = false;
		combatEndedAt = -1L;
	}

	private boolean hasCombatActivity(long now)
	{
		return combatActivity != null
			&& (combatActive || isFresh(combatEndedAt, now, COMBAT_GRACE_MILLIS));
	}

	private static boolean isFresh(long observedAt, long now, long timeout)
	{
		return observedAt >= 0L
			&& now >= observedAt
			&& now - observedAt < timeout;
	}

	private static String limit(String activity)
	{
		return activity.length() <= MAX_ACTIVITY_LENGTH
			? activity
			: activity.substring(0, MAX_ACTIVITY_LENGTH);
	}
}

